ST.xhtml:
// =============================================================================
// 场景：清理 CSV 字段：删除所有 `	` Tab 字符；或者把电话号码中的 `-` 和 ` ` 都删掉只保留数字。
// 价值：比 `FindAndDelete` 调用更省事——单字符常量直接写入参数，不用预先声明 STRING 变量取地址。
// 验证步骤：
//   1. 引用 Tc2_Utilities
//   2. 编译 + 登录 + 运行
//   3. 在线写触发位 TRUE，monitor 输出变量
// =============================================================================
// 第一步：删除所有空格
IF bClean THEN
    nRemoved := FindAndDeleteChar(pSrcString  := ADR(sPhoneRaw),
                                  sDeleteChar := ' ',
                                  pDstString  := ADR(sPhoneNum),
                                  nDstSize    := SIZEOF(sPhoneNum));
    // 第二步：在结果上再删 '-'（in-place 安全）
    nRemoved := nRemoved + FindAndDeleteChar(pSrcString  := ADR(sPhoneNum),
                                             sDeleteChar := '-',
                                             pDstString  := ADR(sPhoneNum),
                                             nDstSize    := SIZEOF(sPhoneNum));
    bClean := FALSE;
END_IF;
